/**
 * Shared marketing types — hand-maintained until pnpm db:types regeneration
 * includes these interface shapes.
 *
 * NOTE: AudienceFilter was previously in lib/supabase/types.ts but was
 * removed during M6 schema regeneration. Defined here to avoid scatter.
 */

// Legacy flat audience filter shape — supported by get_campaign_audience_count RPC
export interface AudienceFilter {
  tags?: string[]
  last_visit_days?: number
  min_spent_cents?: number
  max_spent_cents?: number
  location_ids?: string[]
}

// M2 extended shape with OR/NOT groups — backward compat via legacy serialization
export interface AudienceFilterGroup {
  op: 'AND' | 'OR'
  conditions: Array<{
    type: 'tags' | 'last_visit_days' | 'min_spent_cents' | 'max_spent_cents' | 'location_ids'
    value: string
  }>
}

export interface ExtendedAudienceFilter {
  groups: AudienceFilterGroup[]
  exclude: AudienceFilter
}

// Marketing campaign status (derived — never set by UI)
export type CampaignStatus =
  | 'draft'
  | 'scheduled'
  | 'sending'
  | 'sent'
  | 'paused'
  | 'active'
  | 'cancelled'
  | 'failed'

export type CampaignType = 'manual' | 'automated'
export type CampaignChannel = 'email' | 'sms' | 'both'

